css:
:where(.wtyg-map-site_animal_fighting){--bg:#110f0f; --panel:#181515; --panel2:#211d1c; --line:#38302e; --ink:#ebe5de; --mute:#a99f98; --faint:#80766f;
  --on:#3a2f2f; --onl:#6a5654; --link:#bfb0c6;}
:where(.wtyg-map-site_animal_fighting) *{box-sizing:border-box}
:where(.wtyg-map-site_animal_fighting),:where(.wtyg-map-site_animal_fighting){margin:0;height:100%;background:var(--bg);color:var(--ink);font:14px/1.45 "Marcellus",Georgia,serif}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="app"],#wtyg-noid-app){position:fixed;inset:0;display:flex}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="side"],#wtyg-noid-side){width:360px;max-width:100%;background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column;z-index:500}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="side"],#wtyg-noid-side) header{padding:16px 16px 10px;border-bottom:1px solid var(--line)}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="side"],#wtyg-noid-side) h1{font:400 23px/1.15 "Uncial Antiqua","Marcellus",Georgia,serif;margin:0 0 6px;letter-spacing:.5px}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="side"],#wtyg-noid-side) .lede{margin:0;color:var(--mute);font-size:13px}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="scroll"],#wtyg-noid-scroll){overflow:auto;flex:1;padding:6px 16px 24px}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="mapwrap"],#wtyg-noid-mapwrap){flex:1;position:relative;min-width:0}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="mapwrap"],#wtyg-noid-mapwrap) :is([data-wtyg-id="map"],#wtyg-noid-map){position:absolute;inset:0}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="map"],#wtyg-noid-map){background:#0c0a0a}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="globe"],#wtyg-noid-globe){position:absolute;inset:0;z-index:450;background:#0c0a0a}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="globe"],#wtyg-noid-globe)[hidden]{display:none}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="mapwrap"],#wtyg-noid-mapwrap).globe .leaflet-control-attribution{display:none}
:where(.wtyg-map-site_animal_fighting) .maplibregl-ctrl-attrib{background:rgba(17,15,15,.8)!important;color:var(--mute)!important}
:where(.wtyg-map-site_animal_fighting) .maplibregl-ctrl-attrib-inner{color:var(--mute)}
:where(.wtyg-map-site_animal_fighting) .maplibregl-ctrl-attrib a{color:var(--mute)!important}
:where(.wtyg-map-site_animal_fighting) .maplibregl-ctrl-attrib-button{filter:invert(1)}
:where(.wtyg-map-site_animal_fighting) .maplibregl-ctrl-group{background:#1d1918!important}
:where(.wtyg-map-site_animal_fighting) .maplibregl-ctrl-group button .maplibregl-ctrl-icon{filter:invert(1)}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="worldbtn"],#wtyg-noid-worldbtn){position:absolute;left:10px;top:84px;z-index:700;display:flex;align-items:center;gap:6px;background:#1d1918;color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:5px 10px;font:13px "Marcellus",Georgia,serif;cursor:pointer;box-shadow:0 1px 5px rgba(0,0,0,.4)}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="worldbtn"],#wtyg-noid-worldbtn):hover{background:#272120}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="tr"],#wtyg-noid-tr){position:absolute;right:10px;top:10px;z-index:800;display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;align-items:flex-start;max-width:calc(100% - 380px)}
:where(.wtyg-map-site_animal_fighting) .bm{flex:none;display:flex;gap:4px;background:rgba(24,21,21,.9);border:1px solid var(--line);border-radius:999px;padding:3px}
:where(.wtyg-map-site_animal_fighting) .bm button{background:none;border:0;color:var(--mute);padding:4px 10px;border-radius:999px;font:12px "Marcellus",Georgia,serif;cursor:pointer}
:where(.wtyg-map-site_animal_fighting) .bm button.on{background:var(--on);color:var(--ink)}
:where(.wtyg-map-site_animal_fighting) h2{font:600 12px/1 "Marcellus",Georgia,serif;text-transform:uppercase;letter-spacing:.09em;color:var(--mute);margin:18px 0 8px}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="q"],#wtyg-noid-q){width:100%;margin-top:10px;background:var(--panel2);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:14px "Marcellus",Georgia,serif}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="q"],#wtyg-noid-q)::placeholder{color:var(--faint)}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="shown"],#wtyg-noid-shown){color:var(--faint);font-size:12px;margin:8px 2px 0}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="shown"],#wtyg-noid-shown) b{color:var(--ink);font-weight:400}
:where(.wtyg-map-site_animal_fighting) .kd{border-top:1px solid var(--line);margin-top:12px}
:where(.wtyg-map-site_animal_fighting) .grp{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:12px}
:where(.wtyg-map-site_animal_fighting) .grp button[data-all]{background:none;border:1px solid var(--line);color:var(--mute);border-radius:999px;padding:3px 10px;font:12px "Marcellus",Georgia,serif;cursor:pointer}
:where(.wtyg-map-site_animal_fighting) .grp button[data-all]:hover{color:var(--ink);border-color:var(--onl)}
:where(.wtyg-map-site_animal_fighting) .kfold{all:unset;cursor:pointer;display:flex;align-items:center;gap:8px;font:400 17px "Marcellus",Georgia,serif;color:var(--ink);flex:1}
:where(.wtyg-map-site_animal_fighting) .kfold .ar{color:var(--mute);width:12px;font-size:12px}
:where(.wtyg-map-site_animal_fighting) .kfold .kn{color:var(--faint);font-size:12px;margin-left:6px}
:where(.wtyg-map-site_animal_fighting) .row{display:flex;align-items:flex-start;gap:9px;padding:6px 4px;border-radius:6px;cursor:pointer}
:where(.wtyg-map-site_animal_fighting) .row:hover{background:var(--panel2)}
:where(.wtyg-map-site_animal_fighting) .row input{margin:3px 0 0;accent-color:#8a7472}
:where(.wtyg-map-site_animal_fighting) .sw{flex:0 0 10px;height:10px;border-radius:50%;margin-top:5px;box-shadow:0 0 0 1px rgba(246,240,236,.35)}
:where(.wtyg-map-site_animal_fighting) .row .t{flex:1}
:where(.wtyg-map-site_animal_fighting) .row .n{color:var(--faint);font-variant-numeric:tabular-nums;font-size:12px;margin-top:1px}
:where(.wtyg-map-site_animal_fighting) .row small{display:block;color:var(--faint);font-size:12px}
:where(.wtyg-map-site_animal_fighting) .key{display:grid;grid-template-columns:16px 1fr;gap:6px 8px;align-items:center;font-size:12px;color:var(--mute);margin:6px 0}
:where(.wtyg-map-site_animal_fighting) .key i{width:12px;height:12px;border-radius:50%;display:block;justify-self:center}
:where(.wtyg-map-site_animal_fighting) .note{color:var(--mute);font-size:12.5px}
:where(.wtyg-map-site_animal_fighting) .note p{margin:6px 0}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="aboutbtn"],#wtyg-noid-aboutbtn){margin-top:10px;width:100%;background:#231e1d;border:1px solid #463c39;color:var(--ink);border-radius:8px;padding:8px 10px;font:14px "Marcellus",Georgia,serif;cursor:pointer;text-align:left}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="aboutbtn"],#wtyg-noid-aboutbtn):hover{background:#2b2524}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="toggle"],#wtyg-noid-toggle){display:none}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="info"],#wtyg-noid-info){position:fixed;inset:0;z-index:2000;background:rgba(8,6,6,.62);display:flex;align-items:center;justify-content:center;padding:20px}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="info"],#wtyg-noid-info)[hidden]{display:none}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="infobox"],#wtyg-noid-infobox){width:min(760px,96vw);max-height:88vh;display:flex;flex-direction:column;background:var(--panel);border:1px solid var(--line);border-radius:12px;box-shadow:0 18px 60px rgba(0,0,0,.6)}
:where(.wtyg-map-site_animal_fighting) .ihead{display:flex;align-items:center;justify-content:space-between;padding:14px 20px;border-bottom:1px solid var(--line)}
:where(.wtyg-map-site_animal_fighting) .ihead h2{margin:0;font:400 19px "Uncial Antiqua","Marcellus",Georgia,serif;text-transform:none;letter-spacing:.3px;color:var(--ink)}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="infoclose"],#wtyg-noid-infoclose){background:none;border:1px solid var(--line);color:var(--mute);border-radius:999px;width:30px;height:30px;cursor:pointer;font-size:13px}
:where(.wtyg-map-site_animal_fighting) .ibody{padding:14px 22px 22px;overflow:auto}
:where(.wtyg-map-site_animal_fighting) .ibody .note{font-size:13.5px}
:where(.wtyg-map-site_animal_fighting) .ibody table{border-collapse:collapse;width:100%;font-size:12.5px;margin:6px 0 4px}
:where(.wtyg-map-site_animal_fighting) .ibody td,:where(.wtyg-map-site_animal_fighting) .ibody th{text-align:left;padding:4px 6px;border-bottom:1px solid var(--line);color:var(--mute);font-weight:400}
:where(.wtyg-map-site_animal_fighting) .ibody th{color:var(--ink)}
:where(.wtyg-map-site_animal_fighting) .ibody .n{text-align:right;font-variant-numeric:tabular-nums}
:where(.wtyg-map-site_animal_fighting) .leaflet-popup-content-wrapper{background:#1d1918;color:var(--ink);border-radius:10px;box-shadow:0 8px 28px rgba(0,0,0,.5)}
:where(.wtyg-map-site_animal_fighting) .leaflet-popup-tip{background:#1d1918}
:where(.wtyg-map-site_animal_fighting) .leaflet-popup-content{margin:14px 16px;font:13.5px/1.5 "Marcellus",Georgia,serif;max-height:min(60vh,480px);overflow:auto}
:where(.wtyg-map-site_animal_fighting) .leaflet-container a.leaflet-popup-close-button{color:var(--mute)}
:where(.wtyg-map-site_animal_fighting) .gpop .maplibregl-popup-content{background:#1d1918;color:var(--ink);border-radius:10px;padding:14px 16px;font:13.5px/1.5 "Marcellus",Georgia,serif;max-height:min(60vh,480px);overflow:auto;box-shadow:0 8px 28px rgba(0,0,0,.5)}
:where(.wtyg-map-site_animal_fighting) .gpop .maplibregl-popup-tip{border-top-color:#1d1918;border-bottom-color:#1d1918}
:where(.wtyg-map-site_animal_fighting) .gpop .maplibregl-popup-close-button{color:var(--mute);font-size:18px;padding:2px 8px}
:where(.wtyg-map-site_animal_fighting) .af-pop h3{font:600 15.5px/1.3 "Marcellus",Georgia,serif;margin:0 0 4px}
:where(.wtyg-map-site_animal_fighting) .af-pop .meta{color:var(--mute);font-size:12px;margin-bottom:8px}
:where(.wtyg-map-site_animal_fighting) .af-pop .tag{display:inline-block;border:1px solid #5e4f4c;border-radius:999px;padding:0 7px;font-size:11px;color:#ddd3cc;margin:0 4px 2px 0}
:where(.wtyg-map-site_animal_fighting) .af-pop .tag.il{border-color:#8a5560;color:#e0c6cb}
:where(.wtyg-map-site_animal_fighting) .af-pop p{margin:6px 0}
:where(.wtyg-map-site_animal_fighting) .af-pop .fig{color:#e6dfd8;background:#272120;border-radius:6px;padding:6px 8px;font-size:12.5px}
:where(.wtyg-map-site_animal_fighting) .af-pop .where{font-size:12px;color:var(--faint)}
:where(.wtyg-map-site_animal_fighting) .af-pop .src{font-size:12px;color:var(--mute);border-top:1px solid var(--line);margin-top:8px;padding-top:6px}
:where(.wtyg-map-site_animal_fighting) .af-list ol{margin:6px 0 0;padding-left:20px;max-height:300px;overflow:auto}
:where(.wtyg-map-site_animal_fighting) .af-list li{margin:3px 0}
:where(.wtyg-map-site_animal_fighting) .af-list li span{display:block;color:var(--faint);font-size:11px}
:where(.wtyg-map-site_animal_fighting) .af-pop a,:where(.wtyg-map-site_animal_fighting) .af-list a{color:var(--link)}
:where(.wtyg-map-site_animal_fighting) .leaflet-control-attribution{background:rgba(17,15,15,.75)!important;color:var(--faint)!important}
:where(.wtyg-map-site_animal_fighting) .leaflet-control-attribution a{color:var(--mute)!important}
:where(.wtyg-map-site_animal_fighting) .leaflet-bar a{background:#1d1918;color:var(--ink);border-color:var(--line)}
:where(.wtyg-map-site_animal_fighting) .leaflet-bar a:hover{background:#272120}
:where(.wtyg-map-site_animal_fighting) .relief{filter:grayscale(1) invert(1) brightness(.62) contrast(1.15)}
:where(.wtyg-map-site_animal_fighting) .jurimg{filter:brightness(.94) contrast(1.06) saturate(1.12)}
:where(.wtyg-map-site_animal_fighting) .atlasplate{z-index:5}
:where(.wtyg-map-site_animal_fighting) .atlasimg{filter:saturate(1.15) brightness(1.06) hue-rotate(-6deg)}
@media (max-width:760px){:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="app"],#wtyg-noid-app){flex-direction:column-reverse}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="side"],#wtyg-noid-side){width:100%;height:46%;border-right:0;border-top:1px solid var(--line)}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="side"],#wtyg-noid-side).min{height:58px}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="toggle"],#wtyg-noid-toggle){display:block;position:absolute;right:12px;top:12px;background:none;border:1px solid var(--line);color:var(--mute);border-radius:999px;padding:3px 10px;font:12px "Marcellus",Georgia,serif}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="side"],#wtyg-noid-side) header{position:relative}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="tr"],#wtyg-noid-tr){max-width:calc(100% - 60px)}}
